"""Portable local dashboard. No credentials, external scripts or remote actions."""
from html import escape
from pathlib import Path

def build_dashboard(channels, daily_plan, target: Path):
    items = {item["channel_id"]: item for item in daily_plan["channels"]}
    cards = []
    for channel in channels:
        status = items.get(channel["id"], {})
        ready = status.get("ready", False)
        blockers = status.get("blockers", [])
        cards.append(f'''<article class="card"><div class="card-top"><span class="eyebrow">CANAL / {escape(channel["id"])}</span><span class="badge {'good' if ready else ''}">{'Listo' if ready else 'Pendiente de activar'}</span></div>
<h2>{escape(channel["name"])}</h2><p class="muted">{escape(channel["theme"])}</p>
<dl><div><dt>Voz</dt><dd>{escape(str(channel["voice"].get("id") or "Por elegir"))}</dd></div><div><dt>Frecuencia prevista</dt><dd>1 reel / día</dd></div><div><dt>Estilo</dt><dd>{escape(channel["visual"]["style"])}</dd></div></dl>
<details open><summary>{len(blockers)} requisitos pendientes</summary><ul>{''.join('<li>'+escape(item)+'</li>' for item in blockers)}</ul></details></article>''')
    content = TEMPLATE.replace("{{CARDS}}", "".join(cards)).replace("{{DATE}}", escape(daily_plan["date"]))
    content = content.replace("{{COUNT}}", str(len(channels))).replace("{{READY}}", str(sum(bool(i.get("ready")) for i in items.values())))
    target = Path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")
    return target

TEMPLATE = '''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estudio · Ecosistema de reels</title>
<style>
:root{color-scheme:dark;--bg:#0b1117;--panel:#131d27;--line:#2a3743;--muted:#acb9c5;--ink:#f2f6f8;--cyan:#77e0cf;--amber:#ffce86}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 'Segoe UI',sans-serif}header,main,footer{max-width:1240px;margin:auto;padding:28px 36px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.brand{font-weight:700;letter-spacing:.14em;font-size:14px}.brand b{color:var(--cyan)}nav a{color:var(--muted);margin-left:24px;text-decoration:none}.hero{padding:40px 0 28px}.eyebrow{font-size:11px;letter-spacing:.14em;color:var(--cyan);font-weight:600}h1{font-size:clamp(34px,5vw,58px);line-height:1.1;letter-spacing:-.04em;margin:15px 0 20px;max-width:780px}h2{font-size:27px;letter-spacing:-.025em;line-height:1.2;margin:18px 0 8px}h3{font-size:20px;margin:0 0 14px}.muted{color:var(--muted)}.lead{font-size:18px;color:var(--muted);max-width:780px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:25px 0 38px}.stat{padding:20px 24px;border:1px solid var(--line);border-radius:14px}.stat strong{display:block;font-size:28px;color:var(--cyan)}.stat span{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.card{padding:26px;background:var(--panel);border:1px solid var(--line);border-radius:18px}.card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.badge{font-size:11px;font-weight:600;background:#3a2e20;color:var(--amber);padding:5px 10px;border-radius:20px;white-space:nowrap}.good{background:#163a33;color:var(--cyan)}dl{margin:24px 0}dl div{display:flex;justify-content:space-between;gap:22px;padding:8px 0;border-bottom:1px solid var(--line)}dt{color:var(--muted);font-size:13px}dd{margin:0;text-align:right;font-size:13px;max-width:60%}details{margin-top:20px}summary{cursor:pointer;color:var(--amber);font-size:13px}li{font-size:13px;color:var(--muted);margin:5px 0}ul{padding-left:19px}.section{margin-top:48px}.steps{display:flex;flex-wrap:wrap;gap:10px;padding:22px 0}.steps span{border:1px solid var(--line);border-radius:9px;padding:10px 16px;font-size:13px}.steps i{align-self:center;color:var(--cyan)}.split{display:grid;grid-template-columns:1fr 1fr;gap:24px}.small{font-size:13px;color:var(--muted)}.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.section-title h2{margin:0}.note{border-left:3px solid var(--amber);padding:12px 18px;background:#231f1a;color:#e1cab0;font-size:13px;margin:16px 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:block;font-size:13px;color:var(--muted)}input,textarea,select{display:block;width:100%;background:#0d151e;border:1px solid #3c4c59;border-radius:8px;padding:11px 12px;color:var(--ink);font:inherit;margin-top:6px}textarea{min-height:82px;resize:vertical}.wide{grid-column:1/-1}button{background:var(--cyan);color:#09221e;border:0;padding:13px 22px;border-radius:9px;font-weight:700;cursor:pointer;margin-top:20px}button:hover{background:#9aecde}footer{color:var(--muted);font-size:12px;border-top:1px solid var(--line);margin-top:50px}.sr{position:absolute;width:1px;height:1px;overflow:hidden}@media(max-width:780px){header,main,footer{padding:20px}.grid,.split,.form-grid{grid-template-columns:1fr}.stats{gap:8px}.stat{padding:14px}.card{padding:20px}nav{display:none}.wide{grid-column:auto}.card-top{align-items:flex-start;flex-direction:column}}
</style></head><body><header><div class="brand"><b>◈</b> ESTUDIO / REELS</div><nav><a href="#canales">Canales</a><a href="#produccion">Producción</a><a href="#nuevo">Nuevo canal</a></nav></header><main>
<section class="hero"><span class="eyebrow">UN SISTEMA COMÚN · IDENTIDADES PROPIAS</span><h1>Todos tus canales.<br>Un mismo estudio.</h1><p class="lead">Producción compartida, calidad por canal y trabajo local. Cada mejora del sistema se puede aplicar a todo el ecosistema.</p></section>
<div class="stats"><div class="stat"><strong>{{COUNT}}</strong><span>canales registrados</span></div><div class="stat"><strong>{{READY}}</strong><span>listos para producción central</span></div><div class="stat"><strong>1 / día</strong><span>objetivo por canal · YouTube + TikTok</span></div></div>
<section id="canales"><div class="section-title"><h2>Tu estudio</h2><span class="small">Estado local · {{DATE}}</span></div><div class="grid">{{CARDS}}</div><div class="note">La producción central sigue en migración. Un trabajo planificado no es un vídeo creado ni una publicación. La activación exige completar los requisitos y comprobar el primer reel de principio a fin.</div></section>
<section class="section" id="produccion"><span class="eyebrow">PRODUCCIÓN</span><h2>El mismo recorrido para cada idea</h2><div class="steps"><span>Fuentes y guion</span><i>→</i><span>Imagen y voz</span><i>→</i><span>Montaje local</span><i>→</i><span>Revisión independiente</span><i>→</i><span>Publicación verificada</span></div><div class="split"><div class="card"><h3>Tu PC hace el trabajo rutinario</h3><p class="muted">Calendario, archivos, caché, montaje, subtítulos y comprobaciones técnicas. Una tarea de GPU a la vez.</p><p class="small">La interpolación y generación local se aplican según el perfil y la calidad comprobada de cada canal.</p></div><div class="card"><h3>Los agentes deciden y revisan</h3><p class="muted">Terra para guion y dirección visual. Sol para revisión independiente. Luna para metadatos derivados.</p><p class="small">Modelos iniciales sujetos a evaluación. El ahorro real se medirá por reel aceptado.</p></div></div></section>
<section class="section" id="nuevo"><span class="eyebrow">NUEVA IDEA</span><h2>Cuéntanos tu próximo canal</h2><p class="muted">Guarda un briefing y entrégalo a Codex para registrar el canal. Se conservarán las decisiones aprobadas y se preguntará solo lo que falte.</p><form id="brief" class="card"><div class="form-grid">
<label>Nombre del canal<input name="name" required placeholder="El nombre de tu nueva idea"></label><label>Temática<input name="theme" required placeholder="Qué descubrirá tu audiencia"></label>
<label>Libro o fuente principal<input name="source_title" required placeholder="Título, autor y edición"></label><label>Audiencia<input name="audience" placeholder="Público, idioma y temas excluidos"></label>
<label class="wide">Estilo artístico<textarea name="visual_style" required placeholder="Referencias, paleta, personajes y movimiento"></textarea></label>
<label>Proveedor de voz<input name="voice_provider" placeholder="Google, voz local…"></label><label>Voz y tono<input name="voice_id" placeholder="Si ya lo tienes decidido"></label>
<label>Cuenta de YouTube<input name="youtube_account" placeholder="ID del canal; nunca contraseñas"></label><label>Cuenta de TikTok<input name="tiktok_account" placeholder="@identificador"></label>
<label class="wide">Logotipo y portada<textarea name="branding_brief" placeholder="Qué quieres transmitir y elementos imprescindibles"></textarea></label>
<label>Publicación<select name="release_mode"><option value="awaiting_user_policy">Lo decidiré al configurar</option><option value="automatic_after_qa">Automática al superar calidad</option><option value="manual_review">Quiero revisar cada vídeo</option></select></label>
</div><button type="submit">Descargar briefing del canal</button><p id="notice" role="status" class="small">Todo ocurre en este navegador. No se envían datos ni se crean cuentas.</p></form></section></main><footer>ESTUDIO / REELS · Configuración y código compartidos. Medios y credenciales en almacenamiento local.</footer>
<script>document.getElementById('brief').addEventListener('submit',function(event){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));const slug=s=>s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');values.sources=[{id:slug(values.source_title)||'fuente-principal',title:values.source_title,redistribute:false}];delete values.source_title;const blob=new Blob([JSON.stringify(values,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=(slug(values.name)||'nuevo-canal')+'-brief.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('notice').textContent='Briefing descargado. Entrégalo a Codex para registrar la ficha y cerrar los datos pendientes.'});</script></body></html>'''
